<?php use kartik\date\DatePicker;use kartik\select2\Select2;use yii\helpers\Html;use yii\widgets\ActiveForm;$form=ActiveForm::begin()?>
<?=$this->render('_class_summary',['model'=>$class])?><div class="row"><div class="col-md-6"><?=$form->field($model,'meeting_number')->textInput(['type'=>'number'])?><?=$form->field($model,'schedule_date')->widget(DatePicker::class,['pluginOptions'=>['format'=>'yyyy-mm-dd','autoclose'=>true]])?><?=$form->field($model,'start_time_slot_id')->widget(Select2::class,['data'=>$timeSlots])?><?=$form->field($model,'end_time_slot_id')->widget(Select2::class,['data'=>$timeSlots])?><?=$form->field($model,'lecture_room_id')->widget(Select2::class,['data'=>$lectureRooms,'options'=>['placeholder'=>'Pilih ruang...'],'pluginOptions'=>['allowClear'=>true]])?><?=$form->field($model,'meeting_type')->dropDownList($model::typeOptions())?></div><div class="col-md-6"><?=$form->field($model,'status')->dropDownList($model::statusOptions())?><?=$form->field($model,'credits')->textInput(['type'=>'number','step'=>'1'])?><?=$form->field($model,'lecturer_id')->widget(Select2::class,['data'=>$lecturers,'options'=>['placeholder'=>'Pilih pengajar...'],'pluginOptions'=>['allowClear'=>true]])?><?=$form->field($model,'location')->textInput()?><?=$form->field($model,'planned_material')->textarea(['rows'=>3])?><?=$form->field($model,'realized_material')->textarea(['rows'=>3])?><?=$form->field($model,'attachment')->textInput(['placeholder'=>'Nama/path lampiran'])?></div></div><div class="text-right"><?=Html::submitButton('<i class="fas fa-save"></i> Simpan',['class'=>'btn btn-success'])?> <?=Html::a('Batal',['meetings','id'=>$class->id],['class'=>'btn btn-warning'])?></div><?php ActiveForm::end()?>
